def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division should truncate toward zero, matching typical integer division in many languages.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python's // truncates toward -inf, so we use int() on true division
                # to truncate toward zero.
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    # After processing, the stack should have exactly one element.
    return stack[0] if stack else 0

