    if nums is None:
        return 0
    # If a plain integer is given, treat it as a single‑element sequence
    if isinstance(nums, int):
        return 1
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in iterator:
        # Skip values that are not comparable (e.g., None, strings)
        try:
            idx = bisect.bisect_left(tails, x)
        except Exception:
