def solve(seq=None):
    """Return the length of the longest strictly increasing subsequence.
    Accepts any iterable of comparable items; if None or empty, returns 0.
    Uses O(n log n) patience sorting algorithm.
    """
    if not seq:
        return 0
    # Convert to list to allow multiple passes
    try:
        nums = list(seq)
    except TypeError:
        # Not iterable
        return 0
    import bisect
    tails = []
    for x in nums:
        # Find the insertion point (first element >= x) for strict increase
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

