def solve(*args, **kwargs):
    """Return length of longest strictly increasing subsequence.
    Accepts the sequence either as a positional argument or as the sole
    keyword argument (any name). Returns 0 for empty or missing input.
    """
    # Determine the input sequence
    if args:
        seq = args[0]
    elif kwargs:
        # Take the first value from keyword arguments
        seq = next(iter(kwargs.values()))
    else:
        return 0
    # Empty check
    if not seq:
        return 0
    # Ensure we can iterate over seq
    try:
        nums = list(seq)
    except TypeError:
        # Not iterable
        return 0
    import bisect
    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

